def S(id, lane, name, status, deps, obj, why, start, read, touch, do, dont, verify, ok="", **kw):
    if isinstance(verify, str): verify = [verify]
    if not ok: ok = verify[0]
    d = dict(id=id, lane=lane, name=name, status=status, deps=deps, obj=obj, why=why, start=start, read=read,
             touch=touch, do=do, dont=dont, verify=verify, ok=ok, user=[], fail=FAIL, doc=DOC, cp=CP, evidence="")
    d.update(kw)
    return d

