# build the Step objects with ids N01... (key -> id), plus the parent N00
_NID = {k["key"]: "N%02d" % (i + 1) for i, k in enumerate(_NS)}
_NID["T02a"] = "T02a"; _NID["T02k"] = "T02k"
def _mk(k):
    deps = [_NID.get(d, d) for d in k["deps"]]
    user = k["user"] or _NUSER
    mile = " (milestone: full regression and your play test)" if k["mile"] else ""
    return S(_NID[k["key"]], "NATIVE", k["name"] + mile, "NOT STARTED", deps, k["obj"], k["why"], _NSTART, k["read"], k["touch"], k["do"], _NDONT, k["verify"], k["ok"], user=user, evidence=k["ev"])
N_STEPS = [S("N00","NATIVE","The game without the emulator (Track D, Option A)","NOT STARTED",["T02k"],
  "Turn the program into a native PC game: no Z80 emulation, no ROM code executed. The game still reads its maze, text, graphics and sound data from the player's own pacman.zip at run time (Option A); nothing of the ROM is shipped. The result must be 1:1 with the emulated port: identical video RAM, colour RAM, sprite registers, sound registers and cycle-exact frame timing in every frame of every test situation.",
  "User request (2026-10-15): remove the emulation layer; Option A (assets from the player's ROM); 1:1 with the arcade as the port now shows it; many small steps of 10 to 20 minutes.",
  "T02a VERIFIED (the hook mechanism exists).","docs/notes/gameplay_routines.md, docs/notes/boot_flow.md, docs/notes/ram_map.md","see the sub-steps",
  ["Method (replace routine by routine inside the running emulator, then remove the emulator): every ROM routine gets a native C++ version (readable, named, in src/game and src/logic) that runs in its place through the hook mechanism of T02a, and is proved identical frame by frame, including its exact cycle cost. The progress meter (ROM instruction addresses still executed) falls step by step to zero (step N48); then the Z80 is removed (N49) and kept only as the reference in the tests (N50).",
   "Order: first the modding steps T02b-T02k as planned (release 1.1.0); then Track D: tools and coverage players (N01-N11; they only need T02a and can be done earlier if you prefer), leaf routines and drawing (N12-N21), the interrupt handler (N22-N27), game flow (N28-N42), sound (N43-N44), scheduler, main loop and boot (N45-N47), proof of zero ROM code (N48), removal (N49-N50), named state (N51-N53), documents (N54); N55 is release 2.0.0.",
   "Step size: one routine family per step, evidence run 1,000,000 frames (about 7 minutes); 3,000,000 frames only at milestones. A step that would take longer than about 20 minutes is split."],
  ["Risks, said in advance: (1) about 0.8% of frames end while a long routine is running; reproducing them exactly needs exact cycle costs and routines that can pause (N06, N17): decision gate with you if it cannot be done. (2) Code that no test situation reaches cannot be proved; N05 lists it and records a decision for each part. (3) The power-on self test (N47) is a decision. (4) 'Identical' means: identical in all the test situations, not a mathematical proof; the coverage report says which situations exist. (5) The graphics, maze, text and sound data stay in the player's ROM: the game still needs pacman.zip."],
  ["The ROM-instruction counter is 0 in all test situations; every replay, coverage and Purist hash identical to the original run; full regression passes."],"Native game identical to the emulated port.",
  user=["Follow the milestone steps (N27, N42, N44, N48, N49): play the test package and tell me OK."],evidence="docs/evidence/N*_*.txt")]
N_STEPS += [_mk(k) for k in _NS]

_iK=[i for i,x in enumerate(STEPS) if x["id"]=="T02k"][0]
STEPS[_iK+1:_iK+1]=N_STEPS

